// === Tab: mySketch ===
//Slight modification of code posted by it looks like 4 different people on OpenProcessing
//Don't know who to credit but this is super cool, I only edited it but it is teaching me a lot about shaders

let Shader,palette;
let speed = 9;//256;
let n = 0.8;
let ctr = 0;
function setup() {
  createCanvas(windowWidth,windowHeight,WEBGL);
	pixelDensity(1);
  noStroke();
}



function draw() {
  shader(Shader);
	Shader.setUniform('pal',palette);
	Shader.setUniform('c',[-sin(frameCount/speed)*0.3-1.0,0.05*cos(2.7+frameCount/speed*1.05)*n]);
	Shader.setUniform('fc',frameCount);
	Shader.setUniform('resolution',[windowWidth,windowHeight]);
  rect(0,0,width,height);
}
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}
function mousePressed() {
	fullscreen(!fullscreen());
}
function preload() {
  Shader=new p5.Shader(this._renderer,`
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`,`
		precision lowp float;
		varying vec2 vTexCoord;
		uniform vec2 resolution;
		uniform sampler2D pal;
		uniform vec2 c;
		uniform int fc;
		vec4 huepal2rcolor(vec3 c) {
      vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
      vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
      return vec4(c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y),1.0);
    }


		void main() {
			vec2 z=vec2(5.*vTexCoord.x-2.5,(5.*vTexCoord.y-2.5)*(resolution.y/resolution.x));
			float x,y;
			int iter=500;
			for(int i=0;i<500;i++) {
				x=(z.x)*(z.x)-(z.y)*(z.y)+c.x;
				y=2.*(z.x)*(z.y)+c.y;
				if((x*x+y*y)>11.6) {iter=i;break;}
				z.x=x;
				z.y=y;
			}
			//gl_FragColor=texture2D(pal,vec2(iter==100?0.:float(iter)/100.,1));
			gl_FragColor = huepal2rcolor(vec3(mod(log(x*x+y*y)+vTexCoord.y,1.),1.0,iter<500?exp(float(iter-500)):1.0));
		}
	`);
	palette=loadImage("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAQAAAAABCAYAAAAxWXB3AAAAAXNSR0IArs4c6QAAAGRJREFUOE9jZGBg+M8ABiwMDAwcSDQyGyZHSIyQPDZzOJCsZoE6AUaDnIRDDGwUmjqYGNwrUHmQOnQxFoQc3FVIykE+AWNai7EwMPxhQOAfFLBB5gyE/uHlAeTYGM5sUEphYAAAjJafAWvSA74AAAAASUVORK5CYII=");
}

